/**
 * Formats a byte count as a human-readable string such as "1.4 MB".
 *
 * @param {number} bytes - the number of bytes to format; must be zero or greater.
 * @param {number} [decimals=1] - how many digits to keep after the decimal point.
 * @returns {string} the formatted size, with a unit suffix such as "KB" or "MB".
 */
function formatBytes(bytes, decimals = 1) {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0;
  let n = bytes;
  while (n >= 1024 && i < units.length - 1) {
    n /= 1024;
    i += 1;
  }
  return `${n.toFixed(decimals)} ${units[i]}`;
}

module.exports = { formatBytes };

clamp-contract-pass.artifact:
/**
 * Clamps a number to the inclusive range [min, max].
 *
 * @param {number} value - the number to clamp.
 * @param {number} min - the lower bound, returned when value falls below it.
 * @param {number} max - the upper bound, returned when value rises above it.
 * @returns {number} value, min or max, whichever lies inside the range.
 */
function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

export default clamp;

