/**
 * Turns an Express-style query string into a plain object.
 *
 * @param {string} search - the query string, with or without a leading "?".
 * @returns {Object} an object whose keys are the query parameter names.
 */
function parseQuery(search) {
  const out = {};
  new URLSearchParams(search.startsWith('?') ? search.slice(1) : search)
    .forEach((v, k) => { out[k] = v; });
  return out;
}

/**
 * Serialises a plain object back into a query string.
 *
 * @param {Object} params - key/value pairs to encode; nested values are JSON-encoded.
 * @param {boolean} encode - whether to percent-encode each key and value.
 * @returns {string} the query string, without a leading "?".
 */
function buildQuery(params, encode) {
  return Object.entries(params)
    .map(([k, v]) => [encode ? encodeURIComponent(k) : k, encode ? encodeURIComponent(v) : v])
    .map(([k, v]) => `${k}=${v}`)
    .join('&');
}
